import {initAudio,setAudioScene,playSound,getAudioSettings,updateAudioSettings,setAudioPaused,getAudioStatus} from './audio.js?v=4';
import {mountMemoryGame} from './memory-game.js?v=4';
import {createPassportStore} from './passport.js?v=4';
import {portraitWidths} from './portrait-sizes.js?v=4';
import {portraitURL} from './artwork.js?v=4';
import {dimensions,questions,characters,sources} from './data.js?v=4';
import {scoreAnswers,matchCharacters} from './scoring.js?v=4';
import {createCardBlob,shareResult,copyResultLink,resultURL} from './share.js?v=4';
const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const KEY='history-soul-v1';
let passportStorage;try{passportStorage=window.localStorage}catch{passportStorage={getItem(){throw Error('blocked')},setItem(){throw Error('blocked')}}}
const passportStore=createPassportStore(passportStorage,characters.map(c=>c.id));
let memorySession=null,audioMeterTimer=null;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(c,cls='',lazy=true)=>`<img class="${cls}" src="${portraitURL(c.id,true)}" srcset="${portraitURL(c.id,true)} 480w, ${portraitURL(c.id)} ${portraitWidths[c.id]||320}w" sizes="${cls==='result-portrait'?'255px':cls==='dialog-portrait'?'180px':'(max-width:760px) 120px, 170px'}" decoding="async" alt="${escape(c.name)}的原创可爱插画" ${lazy?'loading="lazy"':''} width="320" height="360">`;
const charById=id=>characters.find(c=>c.id===id);
const complete=answers=>Array.isArray(answers)&&answers.length===questions.length&&answers.every((v,i)=>Number.isInteger(v)&&v>=0&&v<questions[i].options.length);
function readSave(){try{let s=JSON.parse(localStorage.getItem(KEY));if(!s||s.version!==1||!Array.isArray(s.answers))return null;s.answers=questions.map((q,i)=>Number.isInteger(s.answers[i])&&s.answers[i]>=0&&s.answers[i]<q.options.length?s.answers[i]:null);s.index=Math.max(0,Math.min(questions.length-1,Number(s.index)||0));s.done=!!s.done&&complete(s.answers);return s}catch{return null}}
let saved=readSave(), answers=saved?.answers||Array(questions.length).fill(null), index=saved?.index||0, view='home', result=null, busy=false, lastNext=0, filter='全部', collection='all', query='', toastTimer, modalReturn=null, cardObjectURL=null, dialogGeneration=0;
function persist(done=false){try{localStorage.setItem(KEY,JSON.stringify({version:1,answers,index,done,poolSize:characters.length}));saved=readSave()}catch{toast('浏览器暂不能保存进度；仍可完成本次探索。')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function header(){return `<header class="site-header wrap"><button class="brand" data-action="home" aria-label="历史人格研究所，返回首页"><img src="./assets/favicon.svg" alt=""><span><b>历史人格研究所</b><small>HISTORY SOUL LAB</small></span></button><nav class="header-nav" aria-label="主导航">${[['home','人格探索'],['memory','翻翻乐'],['passport','时空护照'],['gallery','人物图鉴']].map(([id,label])=>`<button class="nav-link ${view===id?'active':''}" data-action="${id}">${label}</button>`).join('')}</nav><button class="sound-button" data-action="audio" aria-label="声音设置" title="声音设置"><span aria-hidden="true">♪</span><span id="sound-badge">音乐</span></button></header>`}
function footer(){return `<footer class="site-footer wrap"><span>每一种性格，都有自己的光。 &nbsp; © 2026 历史人格研究所</span><div class="footer-actions"><button data-action="method">关于这场探索</button><button data-action="privacy">隐私与数据</button></div></footer>`}
function shell(content){memorySession?.destroy();memorySession=null;setAudioPaused(false);setAudioScene(view);app.innerHTML=header()+`<main id="main" class="wrap motion-in">${content}</main>`+footer();window.scrollTo({top:0,behavior:'instant'});document.title='历史人格研究所 · 寻找你的历史同频人';refreshAudioUI()}
function setView(v,hash=v){view=v;if(location.hash!==`#${hash}`)history.replaceState(null,'',`${location.pathname}${location.search}#${hash}`)}
function cleanShared(){if(location.search)history.replaceState(null,'',`${location.pathname}${location.hash}`)}
const featured=['zhaoyun','wangzhaojun','yuanlongping','linhuiyin','mozart','hepburn'];
const collectionOptions=[['all','全部人物'],['new','新来报到'],['china','中国人物'],['world','世界人物'],['women','女性人物'],['favorites','我的收藏'],['discovered','已遇见']];
const newCount=characters.filter(c=>c.isNew).length;
function inCollection(c){const p=passportStore.get();return (collection==='favorites'&&p.favorites.includes(c.id))||(collection==='discovered'&&p.discovered.includes(c.id))||collection==='all'||(collection==='new'&&c.isNew)||(collection==='china'&&c.region==='中国')||(collection==='world'&&c.region==='世界')||(collection==='women'&&c.gender==='女')}
function personCard(c,i,all=false){return `<button class="person-card" data-person="${c.id}" aria-label="认识${escape(c.name)}：${escape(c.title)}"><span class="card-no">${String(characters.indexOf(c)+1).padStart(2,'0')}</span>${passportStore.get().discovered.includes(c.id)?'<span class="new-badge encountered">已遇见</span>':c.isNew?'<span class="new-badge">新朋友</span>':''}${img(c)}<h3>${escape(c.name)}</h3><p>${escape(c.era)} · ${escape(c.role)}</p><span class="mini-tag">${escape(c.title)}</span></button>`}
function home(){setView('home');cleanShared();const hasProgress=answers.some(x=>x!==null);shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="spark">✳</span> 一场跨越时空的自我发现</div><h1>原来，我在历史里<br><span>长这样。</span></h1><p class="hero-desc">如果穿越回历史，你会是谁？<br>是把日子过成诗的苏轼，还是脑洞不停的达·芬奇？<br>跟着直觉，遇见那个与你同频的灵魂。</p><div class="hero-stats"><span><b>20</b> 个生活选择</span><i></i><span><b>${characters.length}</b> 位历史人物</span><i></i><span>约 <b>3</b> 分钟</span></div><button class="primary" data-action="start">开启我的时空之旅 <span class="arrow">↗</span></button><p class="hero-cta-note">没有标准答案，只有更像你的答案</p>${hasProgress?`<button class="resume-link" data-action="resume">${saved?.done?'查看上次的历史人格卡':'继续上次的探索 · 已答 '+answers.filter(x=>x!==null).length+' / 20 题'} →</button>`:''}</div><div class="hero-art"><div class="hero-cast" aria-label="六位个性各异的历史朋友">${["sushi","liqingzhao","einstein","zhugeliang","hepburn","laozi"].map((id,i)=>`<button class="hero-cameo cameo-${i}" data-person="${id}" aria-label="认识${charById(id).name}"><img src="./assets/portraits-v3/${id}-thumb.webp" alt="${charById(id).name}的全新水粉人物肖像" width="240" height="250" ${i<3?'fetchpriority="high"':'loading="lazy"'}><span>${charById(id).name}</span></button>`).join('')}</div><span class="hero-bubble">你，也有一点像我吗？</span><span class="hero-bubble right">正在寻找我的时空搭子 ✧</span><span class="hero-footnote">不同时代，同一种可爱。</span></div></section><div class="divider">YOUR SOUL HAS A HISTORY</div>${playLinks()}<section class="showcase"><div class="section-heading"><div><h2>历史朋友圈，又热闹了一点。</h2><p>${newCount} 位新朋友来了，从三国英雄到现代科学家。</p></div><button class="text-link" data-action="gallery">探索全部 ${characters.length} 位 <span>↗</span></button></div><div class="preview-grid">${featured.map(id=>charById(id)).filter(Boolean).map((c,i)=>personCard(c,i)).join('')}</div><div class="new-collection-link"><button class="text-link" data-action="new-characters">认识全部 ${newCount} 位新朋友 ↗</button></div></section><section class="science-strip"><div><h2>一点心理学，一大点好奇心。</h2><p>以大五人格维度为灵感，用日常选择探索性格。<br>认真设计的趣味游戏，不是专业心理评估。</p></div><div class="mini-dimensions">${[['O','好奇'],['C','秩序'],['E','社交'],['A','共情'],['S','从容']].map(([k,n])=>`<span><i>${k}</i>${n}</span>`).join('')}</div><button class="text-link" data-action="method">我们如何匹配？ ↗</button></section>`)}
function start(fresh=false){cleanShared();if(!fresh&&saved?.done){newTestDialog();return}if(fresh){answers=Array(questions.length).fill(null);index=0;result=null}setView('quiz');persist();renderQuiz()}
function newTestDialog(){openDialog(`<h2 id="dialog-title">再认识自己一次？</h2><p class="dialog-copy">你已经有一张历史人格卡。重新探索会替换这台设备上的上次答案；也可以先回去看看。</p><button class="primary" data-action="fresh">开始新的探索 ↗</button><button class="plain" data-action="last-result" style="width:100%">查看上次结果</button>`)}
const chapters=['生活小偏好','与你和世界','遇见新挑战','更靠近自己'];
function renderQuiz(){const q=questions[index],sel=answers[index],chapter=Math.floor(index/5);shell(`<section class="quiz-shell"><div class="quiz-progress-top"><span>时空探索 · ${chapters[chapter]}</span><span><b>${String(index+1).padStart(2,'0')}</b> / ${questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="答题进度" aria-valuemin="0" aria-valuemax="20" aria-valuenow="${answers.filter(x=>x!==null).length}"><div style="width:${((index+1)/questions.length)*100}%"></div></div><div class="chapter-markers">${chapters.map((s,i)=>`<span class="${i<=chapter?'done':''}">${['Ⅰ','Ⅱ','Ⅲ','Ⅳ'][i]} ${s}</span>`).join('')}</div><div class="question-card"><div class="question-scene"><span class="scene-dot">${['✦','⌁','✳','♡'][chapter]}</span>${escape(q.scene||'日常的一小刻')}</div><h1 tabindex="-1" id="question-title">${escape(q.prompt)}</h1><p class="question-hint">${escape(q.subtitle||'想想近半年的自己，选最接近你日常反应的一项。')}</p><div class="answer-options" role="group" aria-labelledby="question-title">${q.options.map((o,i)=>`<button class="answer-option ${sel===i?'selected':''}" data-option="${i}" aria-pressed="${sel===i}"><span class="option-label">${'ABCD'[i]}</span><span>${escape(o.text)}</span>${sel===i?'<span class="selected-tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div><div class="quiz-bottom"><button class="plain" data-action="previous" ${index===0?'disabled':''}>← 上一题</button><button class="primary" data-action="next" ${sel===null?'disabled':''}>${index===questions.length-1?'揭晓历史同频人':'下一题'} <span class="arrow">→</span></button></div></div><p class="quiet-note">按 1–4 选择，Enter 继续 · 可返回修改 · 进度仅保存在此设备</p><div class="quiz-side-note">${img(charById(['sushi','libai','curie','zhugeliang'][chapter]))}<span>${['把真实的你带来就好。','安静与热闹，都是很好的答案。','跟着日常的你，不必选理想中的你。','再靠近一点，你的历史朋友就到了。'][chapter]}</span></div></section>`);$('#question-title').focus({preventScroll:true})}
function selectOption(n){if(view!=='quiz'||busy||!Number.isInteger(n)||n<0||n>3)return;answers[index]=n;playSound('select');persist();document.querySelectorAll('[data-option]').forEach((b,i)=>{b.classList.toggle('selected',i===n);b.setAttribute('aria-pressed',String(i===n));b.querySelector('.selected-tick')?.remove();if(i===n)b.insertAdjacentHTML('beforeend','<span class="selected-tick" aria-hidden="true">✓</span>')});$('[data-action="next"]').disabled=false}
function next(){const now=performance.now();if(view!=='quiz'||busy||now-lastNext<350||answers[index]===null)return;lastNext=now;if(index<questions.length-1){index++;persist();renderQuiz()}else if(complete(answers)){calculate(true)}}
function calculate(celebrate=false){if(!complete(answers)){index=answers.findIndex(x=>x===null);setView('quiz');renderQuiz();return}const expanded=!!saved?.done&&(saved.poolSize||36)<characters.length;const scores=scoreAnswers(answers);result={scores,matches:matchCharacters(scores)};passportStore.recordQuiz(result.matches[0].character.id,scores,celebrate);persist(true);setView('result');renderResult();if(expanded)toast(`已用原答案匹配 ${characters.length} 位人物，结果可能有所更新。`);if(celebrate){confetti();playSound('complete')}}
function dimensionRows(scores){return dimensions.map(d=>`<div class="dimension"><div class="dimension-top"><b>${escape(d.name)}</b><span>${Math.round(scores[d.key])} / 100</span></div><div class="dimension-line"><div class="dimension-fill" style="width:${Math.max(0,Math.min(100,scores[d.key]))}%"></div></div><div class="dimension-labels"><span>${escape(d.low)}</span><span>${escape(d.high)}</span></div></div>`).join('')}
function tags(c){return `<div class="tag-row">${c.tags.map(t=>`<span class="tag"># ${escape(t)}</span>`).join('')}</div>`}
function mainCard(c,shared=false){return `<section class="result-person"><span class="result-stamp">历史同频<br>认证小卡</span><span class="eyebrow">${shared?'SOMEONE’S HISTORY SOUL':'MY HISTORY SOUL'}</span>${img(c,'result-portrait',false)}<h2>${escape(c.name)}</h2><p class="era">${escape(c.era)} · ${escape(c.role)}</p><div class="result-title">${escape(c.title)}</div><blockquote>“${escape(c.tagline)}”</blockquote>${tags(c)}<p class="card-bottom">在不同的时代，我们有相似的可爱。<br>HISTORY SOUL LAB · 历史人格研究所</p></section>`}
function resultExplanation(c,scores){const nearest=dimensions.map(d=>({d,diff:Math.abs(scores[d.key]-c.vector[d.key])})).sort((a,b)=>a.diff-b.diff).slice(0,2).map(({d})=>`${d.name}上偏向「${scores[d.key]>=60?d.high:scores[d.key]<=40?d.low:'两端之间'}」`).join('，');return `你的回答在${nearest}，与我们为${c.name}创作的画像较接近。${c.description}`}
function renderResult(){if(!result)return home();const {scores,matches}=result,c=matches[0].character;document.title=`我的历史同频人是${c.name} · 历史人格研究所`;shell(`<div class="page-head"><div class="eyebrow">✦ 时空连线成功</div><h1>你的历史同频人，出现了。</h1><p>不是给你贴标签，而是借一个熟悉的灵魂，看见自己的另一面。</p></div><div class="result-layout">${mainCard(c)}<div class="result-details"><section class="info-card"><span class="match-pill">风格接近度 ${matches[0].score}</span><h3>为什么是${escape(c.name)}？</h3><p>${escape(resultExplanation(c,scores))}</p><p class="match-note">接近度是游戏内距离换算，不是概率、百分位或人格准确率。</p></section><section class="info-card"><h3>你的五维性格切片</h3><p>两端各有价值，分数高低不代表好坏。</p>${dimensionRows(scores)}<button class="text-link" data-action="review">查看我的 20 个选择 ↗</button></section></div></div><div class="result-wide"><p class="passport-hint">✦ ${escape(c.name)}已收入时空护照 <button class="text-link" data-action="passport">看看我的足迹 ↗</button></p><div class="share-actions"><button class="primary" data-action="save-card">保存我的人格小卡 <span>↓</span></button><button class="secondary" data-action="share">邀请朋友来测 ↗</button><button class="secondary" data-action="copy">复制结果链接</button></div><div class="insight-grid"><section class="info-card"><span class="insight-kicker">01 · 你的闪光点</span><h3>随身携带的小天赋</h3><p>${escape(c.strength)}</p></section><section class="info-card"><span class="insight-kicker">02 · 给自己一点提醒</span><h3>偶尔，也照顾另一面</h3><p>${escape(c.watchout)}</p></section><section class="info-card"><span class="insight-kicker">03 · 今天就试一试</span><h3>一个刚刚好的小行动</h3><p>${escape(c.habit)}</p></section></div><section class="info-card"><h3>历史里的 TA，真的做过什么？</h3><p>${escape(c.story)}</p><p class="match-note">史实与人格画像分开呈现；这里的性格解读属于创作，不是对历史人物的心理测量。</p></section><section style="margin-top:28px"><div class="section-heading"><div><h2>你的性格，还藏着这些影子</h2><p>相近的分数也可能对应不同人物，看看哪一面更像你。</p></div></div><div class="runner-grid">${matches.slice(1,3).map(m=>`<button class="runner" data-person="${m.character.id}">${img(m.character)}<div><h3>${escape(m.character.name)}</h3><p>${escape(m.character.title)}<br>风格接近度 ${m.score} ↗</p></div></button>`).join('')}</div></section>${friendSection(c)}<p class="quiet-note">你远比一张人格卡丰富。结果是此刻的自我描述，换个情境、换一天，也可能不同。</p><div style="text-align:center;margin-top:15px"><button class="plain" data-action="method">查看计分方法</button><button class="plain" data-action="restart">再探索一次 ↻</button></div></div>`);document.title=`我的历史同频人是${c.name} · 历史人格研究所`}
function friendSection(c){return `<section class="friend-card"><h3>如果我们一起穿越，会是什么搭子？</h3><p>选一位朋友测到的人物，解锁你们的历史组合。只是角色互动彩蛋。</p><div class="friend-pick"><select id="friend-select" aria-label="朋友测到的历史人物">${['灵感派','谋略派','行动派','探索派','温暖派'].map(category=>`<optgroup label="${category}">${characters.filter(x=>x.category===category).map(x=>`<option value="${x.id}" ${x.id==='libai'&&x.id!==c.id?'selected':''}>${x.name} · ${x.title}</option>`).join('')}</optgroup>`).join('')}</select><button class="secondary" data-action="friend">解锁搭子 ↗</button></div><div id="friend-result" aria-live="polite"></div></section>`}
function revealFriend(){const c=result.matches[0].character,f=charById($('#friend-select').value);const vals=dimensions.map(d=>({d,gap:Math.abs(c.vector[d.key]-f.vector[d.key])})).sort((a,b)=>b.gap-a.gap);let title,copy;if(c.id===f.id){title='双倍同频 · 灵魂分身组';copy='你们像同一本书的不同版本。一起做喜欢的事很自在，也别忘了给彼此留一点不同的空间。'}else if(vals[0].gap<35){title='默契搭子 · 心照不宣组';copy='你们的角色画像有不少共同点，可能连聊天的节奏都合拍。不妨各带一个新点子，给默契加一点惊喜。'}else{title='互补搭子 · 脑洞施工队';copy=`一个开窗，一个搭梯。你们的角色画像在「${vals[0].d.name}」上差异更大，试着让彼此的擅长轮流当主角。`}$('#friend-result').innerHTML=`<div class="friend-result"><h4>${escape(c.name)} × ${escape(f.name)}<br><span style="font-size:12px;display:block;margin-top:8px">${title}</span></h4><p>${copy}</p><p style="font-size:10px;margin-top:10px">仅比较游戏角色画像，不预测真实关系或相处结果。</p></div>`}
function gallery(){cleanShared();setView('gallery');shell(`<div class="page-head"><div class="eyebrow">THE LITTLE HISTORY CLUB</div><h1>${characters.length} 个灵魂，${characters.length} 种可爱。</h1><p>从诗人到科学家，从探索者到行动派。<br>${newCount} 位新朋友加入，跨越朝代与地域，遇见更多可能。</p></div><div class="collection-row" role="group" aria-label="人物范围">${collectionOptions.map(([id,label])=>`<button class="collection-chip ${collection===id?'active':''}" data-collection="${id}" aria-pressed="${collection===id}">${label}${id==='new'?` <span>${newCount}</span>`:''}</button>`).join('')}</div><div class="gallery-controls"><div class="filter-row">${['全部','灵感派','谋略派','行动派','探索派','温暖派'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><input class="search" id="person-search" placeholder="搜索姓名、别名、朝代或标签…" aria-label="搜索历史人物" value="${escape(query)}"></div><p class="gallery-count" id="gallery-count" role="status" aria-live="polite"></p><section class="gallery-grid" id="gallery-grid" aria-label="历史人物图鉴"></section><div class="gallery-cta"><button class="primary" data-action="start">哪一位是我？去测一测 ↗</button></div>`);updateGallery()}
function updateGallery(){const term=query.trim().toLocaleLowerCase();const list=characters.filter(c=>inCollection(c)&&(filter==='全部'||c.category===filter)&&(!term||[c.name,c.era,c.role,c.title,c.category,...c.tags,...(c.aliases||[])].join(' ').toLocaleLowerCase().includes(term)));$('#gallery-count').textContent=`找到 ${list.length} / ${characters.length} 位历史朋友 · 点击小卡认识 TA`;$('#gallery-grid').innerHTML=list.length?list.map((c,i)=>personCard(c,i,true)).join(''):'<div class="empty-state">这个组合下还没有朋友。换个关键词或看看全部人物吧。<br><button class="text-link" data-action="reset-gallery">重置筛选 →</button></div>';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});document.querySelectorAll('[data-collection]').forEach(b=>{b.classList.toggle('active',b.dataset.collection===collection);b.setAttribute('aria-pressed',String(b.dataset.collection===collection))})}
function showPerson(id){const c=charById(id);if(!c)return;openDialog(`${img(c,'dialog-portrait',false)}<h2 id="dialog-title">${escape(c.name)}</h2><p class="dialog-sub">${escape(c.era)} · ${escape(c.role)} · ${escape(c.title)}</p>${tags(c)}<p class="dialog-copy">${escape(c.description)}</p><h3>历史小档案</h3><p class="dialog-copy">${escape(c.story)}</p>${c.aliases?.length?`<p class="alias-note">你也可能叫 TA：${c.aliases.map(escape).join('、')}</p>`:''}<p class="source-label">人物性格与搭子设定均为趣味创作。</p><button class="secondary favorite-button" data-favorite="${c.id}" aria-pressed="${passportStore.get().favorites.includes(c.id)}">${passportStore.get().favorites.includes(c.id)?'♥ 已收藏这位朋友':'♡ 收藏这位朋友'}</button><button class="primary" data-action="modal-start">测测我与谁同频 ↗</button>`)}
function method(){cleanShared();setView('method');shell(`<div class="page-head"><div class="eyebrow">A LITTLE SCIENCE, A LOT OF CURIOSITY</div><h1>有依据，也有想象力。</h1><p>把匹配逻辑摊开来讲，让好奇心明明白白。</p></div><div class="method-content"><div class="method-intro">本游戏借鉴大五人格的五个连续维度来组织题目，但题目、中文表述和人物画像是本项目原创，<strong>未经信度、效度与常模验证</strong>。它是一场有结构的自我探索，不是标准心理量表或心理诊断。</div><section class="info-card"><h3>01 / 我们在观察什么？</h3><p>请按近半年的日常表现回答。每个维度都有两端，两端各有适合的情境；没有更高级的人格。</p><div class="method-dimensions">${dimensions.map(d=>`<div><h4>${d.key} · ${escape(d.name)}</h4><p>${escape(d.description)}</p><p>${escape(d.low)} ↔ ${escape(d.high)}</p></div>`).join('')}</div><p class="match-note">S 是对情绪稳定方向的趣味表达，和大五中的负性情绪方向相反；不代表心理健康、抗压能力或疾病状态。</p></section><section class="info-card"><h3>02 / 答案怎样变成结果？</h3><p>20 道题，每个维度 4 题。每个选项在对应维度上记为 0、33、67 或 100；选项顺序有变化，部分题采用反向方向。每个维度取 4 题的平均值，并以 0–100 显示。</p><p>将你的五维向量与 ${characters.length} 个人物的创作向量逐一比较，五个维度等权，按均方根距离从近到远排序：<code>距离 = √(Σ(你的分数 − 人物分数)² / 5)</code>。<code>接近度 = 100 − 距离</code>，显示时四舍五入。</p><p>接近度仅是这个游戏内的相似指标，不是「你有多少概率就是 TA」，也不是人群百分位。前三名差距很小时，多个人物都可作为阅读视角。同分按固定的人物顺序排序，不随机制造稀有结果。</p></section><section class="info-card"><h3>03 / 历史人物真的做过人格测试吗？</h3><p>没有。人物向量、趣味称号和解读由创作者根据常见文化印象设计，不是历史人物的科学测量，也不代表对其全部行为的评价。卡片中的历史小档案与性格文案分开呈现。</p><p>我们不设人格好坏排名，不编造「万人中仅有 1%」等稀有度，也不根据性别、年龄或身份决定结果。角色搭配是趣味彩蛋，不用于预测真实关系。</p></section><section class="info-card"><h3>04 / 关于短测评与局限</h3><p>短问卷节省时间，但会减少可覆盖的行为细节。情境题也会受到当下心情、理解和自我呈现影响。20 题不能完整描述你，反向题也不自动保证质量。当前结果适合聊天和自我反思，不适合招聘、择偶、诊断或其他重要决策。</p><p>我们没有把参考文献中的已验证量表直接用于本游戏，也没有继承它们的测量效度。</p>${sources.map(s=>`<a class="source-link" href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a><p class="source-label">${escape(s.note||'')}</p>`).join('')}</section><section class="info-card"><h3>05 / 你的答案，只留在这里</h3><p>答案和进度仅存储在当前浏览器，不发送到我们的服务器。分享链接只包含你选择分享的人物 ID，不包含答案或分数；保存的图片包含五维分数，请按自己的意愿分享。</p><button class="text-link" data-action="clear-data">清除此设备上的测评记录 →</button></section><div class="method-end"><button class="primary" data-action="start">带着好奇心，去探索 ↗</button></div></div>`)}
function showShared(id){const c=charById(id);if(!c){toast('这个人物链接没有找到，先从研究所出发吧。');home();return}setView('shared','friend');shell(`<div class="shared-banner">一位朋友向你分享了「${escape(c.name)}」。这里展示的是人物档案，不含朋友的答案或五维分数。</div><div class="page-head"><div class="eyebrow">YOU’VE GOT A HISTORY POSTCARD</div><h1>你的朋友，在历史里是${escape(c.name)}。</h1><p>你们是灵魂分身，还是时空搭子？来发现你的那一位。</p></div><div class="result-layout shared-layout">${mainCard(c,true)}<div><section class="info-card"><h3>${escape(c.title)}</h3><p>${escape(c.description)}</p></section><section class="info-card"><h3>TA 的历史小档案</h3><p>${escape(c.story)}</p></section><button class="primary" style="width:100%" data-action="start">我也来找历史同频人 ↗</button><p class="quiet-note">20 题 · 约 3 分钟 · ${characters.length} 位人物</p></div></div>`)}
function openDialog(html){memorySession?.pause('dialog');clearInterval(audioMeterTimer);audioMeterTimer=null;dialogGeneration++;modalReturn=document.activeElement;dialog.innerHTML=`<div class="dialog-inner"><button class="dialog-close" data-action="close-dialog" aria-label="关闭弹窗">×</button>${html}</div>`;if(!dialog.open)dialog.showModal()}
function closeDialog(){clearInterval(audioMeterTimer);audioMeterTimer=null;dialogGeneration++;dialog.close();if(cardObjectURL){URL.revokeObjectURL(cardObjectURL);cardObjectURL=null}if(modalReturn?.isConnected)modalReturn.focus({preventScroll:true});if(view==='passport')passportView()}
async function saveCard(){if(!result||busy)return;busy=true;openDialog('<h2 id="dialog-title">正在装裱你的小时光…</h2><p class="dialog-copy" style="text-align:center">人物、标签与五维切片，马上装进口袋。</p>');const requestGeneration=dialogGeneration;try{const c=result.matches[0].character,blob=await createCardBlob(c,result.scores);if(!dialog.open||requestGeneration!==dialogGeneration)return;cardObjectURL=URL.createObjectURL(blob);dialog.innerHTML=`<div class="dialog-inner"><button class="dialog-close" data-action="close-dialog" aria-label="关闭弹窗">×</button><h2 id="dialog-title">把另一个我，带走。</h2><p class="dialog-sub">点击下载，或在手机上长按图片保存</p><img class="card-preview" src="${cardObjectURL}" alt="${escape(c.name)}人格分享卡，包含你的五维分数"><a class="primary download-link" href="${cardObjectURL}" download="历史人格卡-${escape(c.name)}.png">下载人格小卡 ↓</a><p class="quiet-note">图片含有你的五维分数，分享前请自行确认。</p></div>`}catch(err){if(requestGeneration!==dialogGeneration)return;closeDialog();toast('小卡生成失败，请重试；也可复制结果链接。');console.error('Card generation failed',err)}finally{busy=false}}
function review(){openDialog(`<h2 id="dialog-title">你的 20 个选择</h2><p class="dialog-sub">点击修改，会重新计算同一份结果</p><div class="review-list">${questions.map((q,i)=>`<div class="review-item"><p>${i+1}. ${escape(q.prompt)}</p><p><strong>${escape(q.options[answers[i]].text)}</strong></p><button data-edit="${i}">修改这个选择 →</button></div>`).join('')}</div>`)}
function privacy(){openDialog('<h2 id="dialog-title">好奇心，也有小隐私。</h2><p class="dialog-copy">答案、进度和结果仅存在当前浏览器。我们没有帐号系统、答题上传或第三方统计。分享链接只包含人物 ID，分享图片会包含五维分数。</p><p class="dialog-copy">清除浏览器数据或使用另一台设备后，无法恢复此前进度。</p><button class="secondary" data-action="clear-data" style="width:100%">清除此设备上的测评记录</button>')}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='confetti';el.setAttribute('aria-hidden','true');el.innerHTML=Array.from({length:26},(_,i)=>`<i style="--x:${(i*37)%100}%;--d:${i*.025}s;--c:${['#c5a8dd','#ebce8d','#b8cdb1','#e6b7bf'][i%4]}"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),3000)}
function playLinks(){const p=passportStore.get();return `<section class="play-links" aria-label="更多时空玩法"><button class="play-link-card" data-action="memory"><span class="play-icon" aria-hidden="true">▧</span><span><small>两分钟的小小冒险</small><strong>人物翻翻乐 <b>↗</b></strong><em>翻开新面孔，配对历史朋友。每天一组新阵容。</em></span></button><button class="play-link-card passport-link" data-action="passport"><span class="play-icon" aria-hidden="true">✦</span><span><small>把遇见的可爱，慢慢收藏</small><strong>我的时空护照 <b>↗</b></strong><em>已经遇见 ${p.discovered.length} / ${characters.length} 位朋友 · ${p.favorites.length} 位收藏</em></span></button></section>`}
function memoryView(){cleanShared();setView('memory');shell('<div id="memory-root"></div>');memorySession=mountMemoryGame($('#memory-root'),{onExit:home,onSound:playSound,onPauseChange:paused=>{setAudioPaused(paused);if(!paused)setAudioScene('memory')},onComplete:({ids})=>{const added=passportStore.recordGame(ids);setAudioScene('result');toast(added.length?`相遇 +${added.length}！新朋友已收入时空护照。`:'这次相遇已记入护照，熟悉的朋友也很可爱。')}})}
function passportView(){cleanShared();setView('passport');const p=passportStore.get(),count=p.discovered.length;const badges=[['初次相遇',count>=1,'遇见第1位人物'],['一桌朋友',count>=6,'遇见6位人物'],['时空小队',count>=18,'遇见18位人物'],['半本历史',count>=36,'遇见36位人物'],['满天星光',count>=72,'遇见全部72位']];shell(`<div class="page-head"><div class="eyebrow">MY LITTLE TIME PASSPORT</div><h1>每一次相遇，都留下星光。</h1><p>完成人格探索或翻翻乐，收集历史朋友。<br>只记录你在此设备上的足迹，不给性格分高低。</p></div><section class="passport-summary"><div class="passport-seal" aria-hidden="true">时空<br>旅人</div><div><span>我的相遇进度</span><strong>${count}<small> / ${characters.length}</small></strong><div class="passport-progress" role="progressbar" aria-label="已遇见人物" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="72"><i style="width:${count/characters.length*100}%"></i></div></div><div class="passport-stat"><b>${p.games}</b><span>次翻牌相聚</span></div><div class="passport-stat"><b>${p.favorites.length}</b><span>位特别收藏</span></div></section><div class="passport-badges">${badges.map(([name,done,note],i)=>`<div class="passport-badge ${done?'earned':''}"><span aria-hidden="true">${['✧','❀','✦','☾','☀'][i]}</span><b>${name}</b><small>${done?'已点亮 · ':''}${note}</small></div>`).join('')}</div><section class="passport-section"><div class="section-heading"><div><h2>刚刚遇见的朋友</h2><p>是你的同频人，也可能是翻牌时的新相识。</p></div>${count?'<button class="text-link" data-action="met-friends">查看全部 ↗</button>':''}</div>${count?`<div class="preview-grid">${p.discovered.slice(-6).reverse().map((id,i)=>personCard(charById(id),i)).join('')}</div>`:'<div class="passport-empty"><span>✧</span><h3>第一页，留给新的相遇。</h3><p>完成一次人格探索，或玩一局翻翻乐，就能点亮你的第一枚印章。</p><div><button class="primary" data-action="start">遇见历史同频人 ↗</button><button class="secondary" data-action="memory">先玩一局翻翻乐</button></div></div>'}</section><section class="passport-section"><div class="section-heading"><div><h2>心动收藏夹</h2><p>打开人物小档案，点一下收藏，把喜欢的朋友留下。</p></div><button class="text-link" data-action="saved-friends">查看收藏 ${p.favorites.length} ↗</button></div>${p.favorites.length?`<div class="preview-grid">${p.favorites.slice(-6).reverse().map((id,i)=>personCard(charById(id),i)).join('')}</div>`:'<button class="collection-invite" data-action="gallery">♡ 去人物图鉴挑选你的特别收藏 ↗</button>'}</section>${p.results.length?`<section class="passport-section"><div class="section-heading"><div><h2>不同日子的我</h2><p>最近12次完成记录。变化是当下回答的切片，不是性格成长排名。</p></div></div><div class="passport-history">${p.results.map(r=>{const c=charById(r.id);return `<button data-person="${r.id}">${img(c,'history-portrait')}<span><b>${c.name}</b><small>${new Date(r.date).toLocaleDateString('zh-CN')} · ${c.title}</small></span><em>认识 TA ↗</em></button>`}).join('')}</div></section>`:''}<div class="passport-bottom"><p>护照仅存于当前浏览器，不会跨设备同步。${p.persistent?'':'当前浏览器无法持久保存，关闭页面后本次足迹可能丢失。'}</p><button class="plain" data-action="clear-passport">清空护照记录</button><button class="text-link" data-action="memory">再遇见几位新朋友 ↗</button></div>`)}
function toggleFavorite(id,button){const p=passportStore.favorite(id),on=p.favorites.includes(id);button.textContent=on?'♥ 已收藏这位朋友':'♡ 收藏这位朋友';button.setAttribute('aria-pressed',String(on));playSound('select');toast(on?'已放入时空护照的收藏夹。':'已取消收藏。');if(view==='gallery')updateGallery()}
function audioDialog(){const a=getAudioSettings();openDialog(`<h2 id="dialog-title">给时光一点声音。</h2><p class="dialog-copy">原创轻柔配乐，陪你慢慢探索。音乐和音效可以分别调整。</p><div class="audio-setting"><div><h3>背景音乐</h3><button class="audio-switch" data-action="audio-music" aria-pressed="${a.musicEnabled}">${a.musicEnabled?'已开启':'已关闭'}</button></div><label for="music-volume">音乐音量 <output id="music-volume-value">${Math.round(a.musicVolume*100)}%</output></label><input id="music-volume" data-audio-volume="musicVolume" type="range" min="0" max="100" value="${Math.round(a.musicVolume*100)}"></div><div class="audio-setting"><div><h3>互动音效</h3><button class="audio-switch" data-action="audio-sfx" aria-pressed="${a.sfxEnabled}">${a.sfxEnabled?'已开启':'已关闭'}</button></div><label for="sfx-volume">音效音量 <output id="sfx-volume-value">${Math.round(a.sfxVolume*100)}%</output></label><input id="sfx-volume" data-audio-volume="sfxVolume" type="range" min="0" max="100" value="${Math.round(a.sfxVolume*100)}"></div><div class="audio-live"><span id="audio-state" role="status"></span><meter id="audio-level" aria-label="音乐输出强度" min="0" max="1" value="0"></meter></div><p class="quiet-note">偏好会保存在此设备。切到后台会自动暂停。</p>`);refreshAudioUI();audioMeterTimer=setInterval(refreshAudioUI,500)}
function refreshAudioUI(){const a=getAudioSettings(),s=getAudioStatus();const names={playing:'轻柔配乐正在播放',pending:'下一次点击后自动播放',muted:'背景音乐已静音',paused:'随游戏一起暂停',background:'后台暂停中',unsupported:'当前浏览器暂不支持声音',error:'声音暂不可用，其他玩法可以继续',uninitialized:'准备好迎接下一次探索'};const label=names[s.musicState]||'声音已就绪';const badge=$('#sound-badge');if(badge)badge.textContent=a.musicEnabled&&a.musicVolume>0?'音乐开':'音乐关';const sound=$('[data-action="audio"]');if(sound){sound.setAttribute('aria-label',`声音设置，${label}`);sound.classList.toggle('muted',!a.musicEnabled||a.musicVolume===0)}if(!dialog.open||!$('#audio-state'))return;$('#audio-state').textContent=label;$('#audio-level').value=s.outputLevel||0;for(const channel of ['music','sfx']){const button=$(`[data-action="audio-${channel}"]`);if(button){button.textContent=a[channel+'Enabled']?'已开启':'已关闭';button.setAttribute('aria-pressed',String(a[channel+'Enabled']))}const out=$('#'+channel+'-volume-value');if(out)out.textContent=Math.round(a[channel+'Volume']*100)+'%'}}

const actions={home,gallery,method,memory:memoryView,passport:passportView,audio:audioDialog,'audio-music':()=>{updateAudioSettings({musicEnabled:!getAudioSettings().musicEnabled});refreshAudioUI()},'audio-sfx':()=>{updateAudioSettings({sfxEnabled:!getAudioSettings().sfxEnabled});refreshAudioUI()},'saved-friends':()=>{collection='favorites';filter='全部';query='';gallery()},'met-friends':()=>{collection='discovered';filter='全部';query='';gallery()},'clear-passport':()=>openDialog('<h2 id="dialog-title">清空时空护照？</h2><p class="dialog-copy">会清除本机的相遇人物、收藏和护照足迹。当前测评答案与翻翻乐最佳成绩会保留。</p><button class="primary" data-action="confirm-passport-clear">清空护照记录</button>'),'confirm-passport-clear':()=>{passportStore.clear();closeDialog();passportView();toast('时空护照已清空。')},'new-characters':()=>{collection='new';filter='全部';query='';gallery()},'reset-gallery':()=>{collection='all';filter='全部';query='';gallery()},start:()=>start(),resume:()=>saved?.done?calculate():start(),fresh:()=>{closeDialog();start(true)},'last-result':()=>{closeDialog();calculate()},previous:()=>{if(index>0){index--;persist();renderQuiz()}},next,restart:newTestDialog,'close-dialog':closeDialog,'modal-start':()=>{closeDialog();start()},'save-card':saveCard,review,privacy,friend:revealFriend,copy:async()=>{try{await copyResultLink(result.matches[0].character);toast('结果链接已复制，发给你的时空搭子吧。')}catch{openDialog(`<h2 id="dialog-title">复制你的分享链接</h2><p class="dialog-copy">此浏览器未开放剪贴板权限，可长按下方链接手动复制。</p><input class="search" style="width:100%" readonly value="${escape(resultURL(result.matches[0].character))}" aria-label="结果分享链接">`)}},share:async()=>{try{const r=await shareResult(result.matches[0].character,result.scores);if(r.method==='clipboard')toast('分享文案与链接已复制。')}catch(e){if(e.name!=='AbortError')actions.copy()}},'clear-data':()=>{openDialog('<h2 id="dialog-title">清除这次探索？</h2><p class="dialog-copy">这会删除当前浏览器保存的答案、进度与结果。已下载的图片不会被删除。</p><button class="primary" data-action="confirm-clear">清除本机测评记录</button><button class="plain" style="width:100%" data-action="close-dialog">先保留</button>')},'confirm-clear':()=>{try{localStorage.removeItem(KEY)}catch{}answers=Array(questions.length).fill(null);saved=null;index=0;result=null;closeDialog();home();toast('此设备上的测评记录已清除。')}};
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').setAttribute('tabindex','-1');$('#main').focus();return}const button=e.target.closest('button,[data-action]');if(!button||button.disabled)return;if(button.dataset.action){actions[button.dataset.action]?.();return}if(button.dataset.favorite){toggleFavorite(button.dataset.favorite,button);return}if(button.dataset.option!==undefined)selectOption(Number(button.dataset.option));if(button.dataset.person)showPerson(button.dataset.person);if(button.dataset.filter){filter=button.dataset.filter;updateGallery()}if(button.dataset.collection){collection=button.dataset.collection;updateGallery()}if(button.dataset.edit!==undefined){index=Number(button.dataset.edit);closeDialog();setView('quiz');persist(false);renderQuiz()}});
document.addEventListener('input',e=>{if(e.target.id==='person-search'){query=e.target.value;updateGallery()}if(e.target.dataset.audioVolume){updateAudioSettings({[e.target.dataset.audioVolume]:Number(e.target.value)/100});refreshAudioUI()}});
document.addEventListener('keydown',e=>{if(dialog.open||view!=='quiz'||e.repeat||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(/^[1-4]$/.test(e.key)){e.preventDefault();selectOption(Number(e.key)-1)}if(e.key==='Enter'&&(!e.target.closest('button')||e.target.closest('[data-option]'))){e.preventDefault();const option=e.target.closest('[data-option]');if(option&&answers[index]!==Number(option.dataset.option))selectOption(Number(option.dataset.option));else next()}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h==='memory')memoryView();else if(h==='passport')passportView();else if(h==='gallery')gallery();else if(h==='method')method();else if(h==='result'&&complete(answers))calculate();else if(h==='quiz')start();else home()});
window.addEventListener('history-audio-change',refreshAudioUI);initAudio();
const shared=new URLSearchParams(location.search).get('character');if(shared)showShared(shared);else if(location.hash==='#memory')memoryView();else if(location.hash==='#passport')passportView();else if(location.hash==='#gallery')gallery();else if(location.hash==='#method')method();else if(location.hash==='#quiz'&&saved&&!saved.done)start();else if(location.hash==='#result'&&saved?.done)calculate();else home();
